export class TreeOfThoughts {
  constructor() {
    this.branches = [];
  }

  addBranch(branch) {
    this.branches.push(branch);
  }

  evaluateBranches(evaluationFunction) {
    return this.branches.map(branch => ({
      branch,
      score: evaluationFunction(branch)
    })).sort((a, b) => b.score - a.score);
  }

  backtrack(branchIndex) {
    if (branchIndex < this.branches.length) {
      this.branches = this.branches.slice(0, branchIndex + 1);
    }
  }

  execute() {
    for (const branch of this.branches) {
      try {
        branch.run();
      } catch (error) {
        console.error('Error executing branch:', error);
      }
    }
  }
}